const incoming = $input.first();
const audio = incoming.binary?.audio;
if (!audio) throw new Error('Expected multipart field named audio');
const original = audio.fileName || 'meeting-audio';
const safe = original.replace(/[^A-Za-z0-9._-]/g, '_').replace(/^_+/, '') || 'meeting-audio';
const stamp = new Date().toISOString().replace(/[-:]/g, '').replace('T', '-').slice(0, 15);
const jobId = `mom-${stamp}-${Math.random().toString(36).slice(2, 6)}`;
// a unique name, so two uploads with the same filename never overwrite each other in the inbox
const uploadName = `${jobId}_${safe}`;
return [{ json: { uploadName, jobId }, binary: { audio } }];
